    // Perform swap using a temporary.
    let tmp = result[i];
    result.set(i, result[j]);
    result.set(j, tmp);

    // Help the verifier connect the concrete update to the postconditions.
    // After these assertions, the ensures should follow.
    assert(result.len() == arr.len());

    assert(result[i as int] == arr[j as int]);
